--
-- setup_wedding(): the first-run "Set up our wedding" step. The signed-in user becomes the first owner, and the
-- wedding starts with the events, budget categories, checklist and decision notes from the prototype.
-- This app holds a single wedding, so it refuses once one exists. Everyone else joins by invitation.

create or replace function public.setup_wedding(
  p_display_name text default null,
  p_wedding_date date default '2028-01-22'
) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_email text;
  v_wedding uuid;
begin
  if v_uid is null then
    raise exception 'Sign in before setting up the wedding.' using errcode = 'insufficient_privilege';
  end if;
  perform pg_advisory_xact_lock(hashtext('public.setup_wedding'));
  if exists (select 1 from public.weddings) then
    raise exception 'The wedding is already set up. Ask Nick or Thuraya to invite you.' using errcode = 'unique_violation';
  end if;

  select u.email into v_email from auth.users u where u.id = v_uid;

  insert into public.weddings (couple_names, wedding_date, date_confirmed, guest_target, total_budget_usd, fx_cop_per_usd)
  values ('Nick & Thuraya', p_wedding_date, false, 40, 15000, 3194)
  returning id into v_wedding;

  insert into public.members (wedding_id, user_id, email, display_name, role)
  values (v_wedding, v_uid, coalesce(v_email, ''),
          coalesce(nullif(trim(p_display_name), ''), split_part(coalesce(v_email, 'Owner'), '@', 1)), 'owner');

  insert into public.events (wedding_id, key, name, is_on, is_fixed, sort)
  select v_wedding, e.key, e.name, e.is_on, e.is_fixed, e.sort
  from (values
      ('welcome', 'Welcome drinks', true, false, 0),
      ('main', 'Ceremony & reception', true, true, 1),
      ('rehearsal', 'Rehearsal dinner', false, false, 2),
      ('dayafter', 'Day-after: Rosario Islands boat day', false, false, 3)
  ) as e (key, name, is_on, is_fixed, sort);

  insert into public.budget_categories (wedding_id, event_id, key, name, amount_usd, is_locked, is_buffer, sort)
  select v_wedding, ev.id, c.key, c.name, c.amount, c.locked, c.key = 'buffer', c.sort
  from (values
      ('venue', 'Venue: hacienda', 2600, false, 'main', 0),
      ('catering', 'Catering & bar', 3300, false, 'main', 1),
      ('florals', 'Florals & décor', 1800, true, 'main', 2),
      ('lighting', 'Lighting: string lights & candles', 700, true, 'main', 3),
      ('photo', 'Photography', 1500, false, 'main', 4),
      ('music', 'Music: DJ & hora loca band', 900, false, 'main', 5),
      ('planner', 'Planner / coordinator', 1200, false, 'main', 6),
      ('attire', 'Attire & beauty', 1200, false, 'main', 7),
      ('cake', 'Cake & desserts', 300, false, 'main', 8),
      ('ceremony', 'Officiant & ceremony', 250, false, 'main', 9),
      ('stationery', 'Stationery & guest website', 150, false, 'main', 10),
      ('favors', 'Favors & welcome bags', 200, false, 'main', 11),
      ('buffer', 'Buffer', 300, false, 'main', 12),
      ('welcome', 'Welcome drinks', 600, false, 'welcome', 13),
      ('rehearsal', 'Rehearsal dinner', 800, false, 'rehearsal', 14),
      ('dayafter', 'Rosario Islands boat day', 1000, false, 'dayafter', 15)
  ) as c (key, name, amount, locked, event_key, sort)
  join public.events ev on ev.wedding_id = v_wedding and ev.key = c.event_key;

  -- Due = wedding date − whole months (clamped to month end), then the fraction as ~30-day steps.
  insert into public.tasks (wedding_id, title, area, assignee, due_date, is_done, months_before, sort)
  select v_wedding, t.title, t.area, t.assignee,
         (p_wedding_date - make_interval(months => floor(t.m)::int))::date - round((t.m - floor(t.m)) * 30)::int,
         t.done, t.m, t.sort
  from (values
      (15, 'Set date window and guest count', 'Planning', 'Both', true, 0),
      (15, 'Agree on a total budget', 'Budget', 'Both', true, 1),
      (15, 'Start the inspiration board', 'Décor', 'Thuraya', true, 2),
      (14.5, 'Decide: legal ceremony at home, symbolic in Cartagena, or legal in Colombia', 'Legal', 'Both', false, 3),
      (14.5, 'Hire a Cartagena wedding planner or coordinator', 'Vendors', 'Nick', false, 4),
      (14, 'Tour hacienda venues (video calls or a scouting trip)', 'Venue', 'Both', false, 5),
      (13, 'Book the hacienda and sign the contract', 'Venue', 'Both', false, 6),
      (13, 'Choose and confirm the wedding date', 'Planning', 'Both', false, 7),
      (12.5, 'Block hotel rooms in the walled city or Getsemaní', 'Travel', 'Nick', false, 8),
      (12, 'Draft the guest list', 'Guests', 'Both', false, 9),
      (12, 'Book the photographer', 'Vendors', 'Thuraya', false, 10),
      (11, 'Send save-the-dates (9–12 months out for destination weddings)', 'Guests', 'Thuraya', false, 11),
      (11, 'Publish a guest info page: flights, hotels, passports, weather', 'Guests', 'Nick', false, 12),
      (10, 'Book the florist and share the inspiration board', 'Florals', 'Thuraya', false, 13),
      (10, 'Book catering and bar, or confirm what the venue includes', 'Catering', 'Planner', false, 14),
      (10, 'Book music: DJ plus a band for the hora loca', 'Music', 'Nick', false, 15),
      (9, 'Plan the lighting: string lights, candles, lanterns', 'Décor', 'Planner', false, 16),
      (9, 'Shop for wedding attire', 'Attire', 'Both', false, 17),
      (9, 'Pick a welcome-drinks spot', 'Events', 'Planner', false, 18),
      (6, 'Send invitations with an RSVP link', 'Guests', 'Thuraya', false, 19),
      (6, 'Book hair and makeup', 'Attire', 'Thuraya', false, 20),
      (6, 'Plan guest transport: airport to hotels, hotels to hacienda', 'Travel', 'Planner', false, 21),
      (5, 'Order welcome bags and favors', 'Décor', 'Thuraya', false, 22),
      (4, 'Menu and cake tasting', 'Catering', 'Both', false, 23),
      (4, 'Finalize the floral and décor plan', 'Florals', 'Planner', false, 24),
      (4, 'Buy wedding rings', 'Attire', 'Both', false, 25),
      (3, 'Chase RSVPs and confirm guest travel', 'Guests', 'Nick', false, 26),
      (3, 'Write the ceremony script and vows', 'Ceremony', 'Both', false, 27),
      (2, 'Build the day-of timeline with the planner', 'Planning', 'Planner', false, 28),
      (2, 'Review the final payment schedule', 'Budget', 'Nick', false, 29),
      (1.5, 'Seating plan', 'Guests', 'Thuraya', false, 30),
      (1, 'Give the final headcount to the caterer', 'Catering', 'Planner', false, 31),
      (1, 'Confirm every vendor: arrival times, contacts on WhatsApp', 'Vendors', 'Planner', false, 32),
      (0.25, 'Final walkthrough at the hacienda', 'Venue', 'Both', false, 33),
      (0.25, 'Withdraw COP cash for final balances and tips', 'Budget', 'Nick', false, 34)
  ) as t (m, title, area, assignee, done, sort);

  insert into public.notes (wedding_id, type, body, created_at)
  select v_wedding, n.type, n.body, now() + make_interval(secs => n.sort)
  from (values
      ('decision', 'Budget set at $15,000 USD. It can flex up or down as life changes.', 0),
      ('decision', 'Guest count: 30–50 people.', 1),
      ('decision', 'Date window: December 2027 to February 2028.', 2),
      ('decision', 'Vision: a Cartagena hacienda with a beautiful courtyard, soft lights, lots of flowers and color.', 3),
      ('decision', 'Events: welcome drinks plus ceremony & reception. Rehearsal dinner and a day-after event are optional.', 4),
      ('decision', 'Our planner can edit tasks, vendors and the timeline. The budget is view-only for the planner.', 5)
  ) as n (type, body, sort);

  return v_wedding;
end $$;

revoke execute on function public.setup_wedding(text, date) from public, anon;
grant execute on function public.setup_wedding(text, date) to authenticated;
